def _src(chapter: int, section: str | None = None) -> SourceRef:
    meta = chapter_meta(chapter)
    return SourceRef(
        book=meta["book"],
        edition=meta["edition"],
        chapter=chapter,
        chapter_title=meta["title"],
        section=section,
        printed_page=meta.get("printed_page"),
        pdf_page=meta.get("pdf_page"),
    )


