        concept=spec["concept"],
        concept_id=cid,
        definition=spec["definition"],
        purpose=spec["purpose"],
        first_principles=list(spec["first"]),
        formula=spec.get("formula"),
        variables=dict(spec.get("variables") or {}),
        assumptions=list(spec.get("assumptions") or []),
        limitations=list(spec.get("limitations") or []),
        relationships=Relationships(
            parent=list(spec.get("parent") or []),
            children=list(spec.get("children") or []),
            dependencies=list(spec.get("parent") or []),
            related=list(spec.get("related") or []),
            opposing=list(spec.get("opposing") or []),
        ),
        causes=list(spec.get("causes") or []),
        effects=list(spec.get("effects") or []),
        industry_impact=dict(INDUSTRY_VARIATIONS.get(cid, {})),
        company_impact=dict(COMPANY_IMPACTS.get(cid, {})),
        investment_impact=list(spec.get("investment_impact") or []),
        valuation_impact=dict(spec.get("valuation_impact") or {}),
        forecast_impact=list(spec.get("forecast_impact") or []),
